const REL=(id,l)=>({two_in:[`બધા ${l[1]} એ ${l[0]} છે (All)`,`બધા ${l[2]} એ ${l[0]} છે (All)`,`કોઈ ${l[1]} એ ${l[2]} નથી (No) ⇒ બંને અલગ-અલગ વર્તુળ, બંને મોટા વર્તુળની અંદર`],nest:[`બધા ${l[1]} એ ${l[0]} છે (All)`,`બધા ${l[2]} એ ${l[1]} છે (All)`,`⇒ ${l[0]} ⊃ ${l[1]} ⊃ ${l[2]} (એકની અંદર એક વર્તુળ)`],sep3:[`${l[0]}, ${l[1]} અને ${l[2]} માંથી કોઈ બે વચ્ચે સંબંધ નથી (No) ⇒ ત્રણ અલગ વર્તુળ`],in_out:[`બધા ${l[1]} એ ${l[0]} છે (All) ⇒ ${l[1]} નું વર્તુળ ${l[0]} ની અંદર`,`${l[2]} એ ${l[0]} પણ નથી અને ${l[1]} પણ નથી (No) ⇒ ${l[2]} નું વર્તુળ બહાર`],ov_in:[`બધા ${l[1]} એ ${l[0]} છે (All)`,`બધા ${l[2]} એ ${l[0]} છે (All)`,`કેટલાક ${l[1]} એ ${l[2]} પણ હોય (Some) ⇒ બંને વર્તુળ એકબીજાને ઓવરલેપ કરે, બંને મોટા વર્તુળની અંદર`],in_ov:[`બધા ${l[1]} એ ${l[0]} છે (All)`,`કેટલાક ${l[2]} એ ${l[0]} પણ હોય (Some)`,`કેટલાક ${l[2]} એ ${l[1]} પણ હોય (Some) ⇒ ${l[2]} નું વર્તુળ મોટા વર્તુળ અને અંદરના વર્તુળ બંનેને અડે`],tri:[`કેટલાક ${l[0]} એ ${l[1]} હોય, કેટલાક ${l[1]} એ ${l[2]} હોય અને કેટલાક ${l[0]} એ ${l[2]} હોય (Some) ⇒ ત્રણેય વર્તુળ એકબીજાને ઓવરલેપ કરે`]})[id];
